package com.bloodwoodstatus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Pulsing glow along the screen edges while you are next to a bloodwood tree
 * but NOT chopping — an unmissable signal that you need to click again.
 * Only shown within the configured distance of a tree.
 */
public class BloodwoodIdleGlowOverlay extends Overlay
{
	private final Client client;
	private final BloodwoodStatusPlugin plugin;
	private final BloodwoodStatusConfig config;

	@Inject
	private BloodwoodIdleGlowOverlay(Client client, BloodwoodStatusPlugin plugin, BloodwoodStatusConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.idleGlow() || !plugin.isNearTree() || plugin.isActive())
		{
			return null;
		}

		final int width = client.getCanvasWidth();
		final int height = client.getCanvasHeight();
		final int thickness = Math.min(config.idleGlowThickness(), Math.min(width, height) / 3);

		// Soft pulse so the glow stands out
		double pulse = config.idleGlowPulse()
			? 0.55 + 0.45 * Math.sin(System.currentTimeMillis() / 250.0)
			: 1.0;

		Color base = config.idleColor();
		int alpha = (int) (config.idleGlowOpacity() * pulse);
		Color edge = new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);
		Color clear = new Color(base.getRed(), base.getGreen(), base.getBlue(), 0);

		// Four edges, each fading from opaque (edge) to transparent (inwards)
		graphics.setPaint(new GradientPaint(0, 0, edge, 0, thickness, clear));
		graphics.fillRect(0, 0, width, thickness);

		graphics.setPaint(new GradientPaint(0, height, edge, 0, height - thickness, clear));
		graphics.fillRect(0, height - thickness, width, thickness);

		graphics.setPaint(new GradientPaint(0, 0, edge, thickness, 0, clear));
		graphics.fillRect(0, 0, thickness, height);

		graphics.setPaint(new GradientPaint(width, 0, edge, width - thickness, 0, clear));
		graphics.fillRect(width - thickness, 0, thickness, height);

		return null;
	}
}

package com.bloodwoodstatus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Draws an aura (outline) and/or tint over the character: green while
 * chopping, red as soon as the character goes idle. Only shown while the
 * player is close to a bloodwood tree.
 */
public class BloodwoodPlayerOverlay extends Overlay
{
	private final Client client;
	private final BloodwoodStatusPlugin plugin;
	private final BloodwoodStatusConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private BloodwoodPlayerOverlay(Client client, BloodwoodStatusPlugin plugin,
		BloodwoodStatusConfig config, ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isNearTree())
		{
			return null;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		boolean active = plugin.isActive();
		Color color = active ? config.activeColor() : config.idleColor();

		// Pulse the red aura so idling stands out more
		if (!active && config.idleGlowPulse())
		{
			double pulse = 0.55 + 0.45 * Math.sin(System.currentTimeMillis() / 250.0);
			color = new Color(color.getRed(), color.getGreen(), color.getBlue(),
				(int) (255 * pulse));
		}

		BloodwoodStatusConfig.HighlightStyle style = config.highlightStyle();

		if (style == BloodwoodStatusConfig.HighlightStyle.OUTLINE
			|| style == BloodwoodStatusConfig.HighlightStyle.BOTH)
		{
			modelOutlineRenderer.drawOutline(local, config.outlineWidth(), color, config.outlineFeather());
		}

		if (style == BloodwoodStatusConfig.HighlightStyle.FILL
			|| style == BloodwoodStatusConfig.HighlightStyle.BOTH)
		{
			Shape hull = local.getConvexHull();
			if (hull != null)
			{
				graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(),
					config.fillOpacity()));
				graphics.fill(hull);
			}
		}

		return null;
	}
}

package com.bloodwoodstatus;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("bloodwoodstatus")
public interface BloodwoodStatusConfig extends Config
{
	enum HighlightStyle
	{
		OUTLINE("Aura (outline)"),
		FILL("Full tint"),
		BOTH("Both");

		private final String name;

		HighlightStyle(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigItem(
		keyName = "highlightStyle",
		name = "Highlight style",
		description = "How your character is highlighted: an aura (outline), a full tint, or both",
		position = 0
	)
	default HighlightStyle highlightStyle()
	{
		return HighlightStyle.OUTLINE;
	}

	@Range(min = 1, max = 15)
	@ConfigItem(
		keyName = "maxDistance",
		name = "Max distance (tiles)",
		description = "Maximum distance to a bloodwood tree within which the effects are shown",
		position = 1
	)
	default int maxDistance()
	{
		return 5;
	}

	@Range(min = 0, max = 10)
	@ConfigItem(
		keyName = "idleGraceTicks",
		name = "Idle grace (ticks)",
		description = "Number of ticks without an animation before the highlight turns red. " +
			"Higher = less flicker between swings, but a slightly slower reaction.",
		position = 2
	)
	default int idleGraceTicks()
	{
		return 2;
	}

	@Alpha
	@ConfigItem(
		keyName = "activeColor",
		name = "Color - active",
		description = "Color while your character is chopping/bleeding the tree",
		position = 3
	)
	default Color activeColor()
	{
		return new Color(0, 200, 0);
	}

	@Alpha
	@ConfigItem(
		keyName = "idleColor",
		name = "Color - idle",
		description = "Color while your character is standing still",
		position = 4
	)
	default Color idleColor()
	{
		return new Color(200, 0, 0);
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Aura width",
		description = "Thickness of the outline around your character (with style 'Aura' or 'Both')",
		position = 5
	)
	default int outlineWidth()
	{
		return 4;
	}

	@Range(min = 0, max = 4)
	@ConfigItem(
		keyName = "outlineFeather",
		name = "Aura feather",
		description = "How softly the edge of the aura fades out (0 = hard edge)",
		position = 6
	)
	default int outlineFeather()
	{
		return 2;
	}

	@Range(min = 10, max = 255)
	@ConfigItem(
		keyName = "fillOpacity",
		name = "Fill opacity",
		description = "Opacity of the tint (with style 'Full tint' or 'Both')",
		position = 7
	)
	default int fillOpacity()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "idleGlow",
		name = "Idle screen glow",
		description = "Show a red glow along the screen edges while you are next to the tree but not chopping",
		position = 8
	)
	default boolean idleGlow()
	{
		return true;
	}

	@Range(min = 20, max = 200)
	@ConfigItem(
		keyName = "idleGlowThickness",
		name = "Glow thickness (px)",
		description = "How far the screen glow extends inwards",
		position = 9
	)
	default int idleGlowThickness()
	{
		return 70;
	}

	@Range(min = 30, max = 255)
	@ConfigItem(
		keyName = "idleGlowOpacity",
		name = "Glow opacity",
		description = "Maximum opacity of the screen glow at the edge",
		position = 10
	)
	default int idleGlowOpacity()
	{
		return 160;
	}

	@ConfigItem(
		keyName = "idleGlowPulse",
		name = "Pulse on idle",
		description = "Make the screen glow and the red aura pulse so idling stands out even more",
		position = 11
	)
	default boolean idleGlowPulse()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showText",
		name = "Show text label",
		description = "Also show the 'CHOPPING' / 'IDLE' panel in the top-left corner",
		position = 12
	)
	default boolean showText()
	{
		return true;
	}
}

package com.bloodwoodstatus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;

public class BloodwoodStatusOverlay extends Overlay
{
	private final BloodwoodStatusPlugin plugin;
	private final BloodwoodStatusConfig config;
	private final PanelComponent panelComponent = new PanelComponent();

	@Inject
	private BloodwoodStatusOverlay(BloodwoodStatusPlugin plugin, BloodwoodStatusConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(OverlayPriority.HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isNearTree() || !config.showText())
		{
			return null;
		}

		panelComponent.getChildren().clear();

		boolean active = plugin.isActive();
		Color color = active ? config.activeColor() : config.idleColor();

		String label = active ? "CHOPPING" : "IDLE";
		panelComponent.getChildren().add(LineComponent.builder()
			.left(label)
			.leftColor(color)
			.build());

		return panelComponent.render(graphics);
	}
}

package com.bloodwoodstatus;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Bloodwood Status",
	description = "Highlights your character green while chopping a bloodwood tree and red the moment you stop. " +
		"Brewed from fresh bloodwood sap by Endlessfur",
	tags = {"woodcutting", "bloodwood", "vampyrium", "idle", "status"}
)
public class BloodwoodStatusPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BloodwoodStatusOverlay overlay;

	@Inject
	private BloodwoodPlayerOverlay playerOverlay;

	@Inject
	private BloodwoodIdleGlowOverlay idleGlowOverlay;

	@Inject
	private BloodwoodStatusConfig config;

	/**
	 * True while the character is actively chopping (an animation is playing).
	 */
	@Getter
	private volatile boolean active = false;

	/**
	 * True while the player is within config.maxDistance() tiles of a
	 * bloodwood tree. The overlays render nothing while this is false.
	 */
	@Getter
	private volatile boolean nearTree = false;

	private final Set<GameObject> bloodwoodTrees = new HashSet<>();

	private int idleTicks = 0;

	@Provides
	BloodwoodStatusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BloodwoodStatusConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(playerOverlay);
		overlayManager.add(idleGlowOverlay);
		idleTicks = 0;
		active = false;
		nearTree = false;
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(playerOverlay);
		overlayManager.remove(idleGlowOverlay);
		bloodwoodTrees.clear();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		if (isBloodwoodTree(object))
		{
			bloodwoodTrees.add(object);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		bloodwoodTrees.remove(event.getGameObject());
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		nearTree = isNearBloodwoodTree(local.getWorldLocation());

		if (!nearTree)
		{
			active = false;
			idleTicks = 0;
			return;
		}

		// -1 = no animation (idle). Anything else means the character is
		// currently doing something (axe swing, pulling the axe back, ...).
		int animation = local.getAnimation();

		if (animation != -1)
		{
			idleTicks = 0;
			active = true;
		}
		else
		{
			idleTicks++;
			if (idleTicks > config.idleGraceTicks())
			{
				active = false;
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			// No despawn events are fired for the old scene's objects when a
			// new scene loads, so clear the set ourselves.
			bloodwoodTrees.clear();
		}

		if (event.getGameState() != GameState.LOGGED_IN)
		{
			active = false;
			nearTree = false;
			idleTicks = 0;
		}
	}

	private boolean isNearBloodwoodTree(WorldPoint playerLocation)
	{
		final int maxDistance = config.maxDistance();
		for (GameObject tree : bloodwoodTrees)
		{
			if (tree.getWorldLocation().distanceTo(playerLocation) <= maxDistance)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Detects bloodwood trees (including the engorged variant) by name, so the
	 * plugin keeps working if Jagex changes object IDs or adds new variants.
	 */
	private boolean isBloodwoodTree(GameObject object)
	{
		ObjectComposition composition = client.getObjectDefinition(object.getId());
		if (composition == null)
		{
			return false;
		}

		if (composition.getImpostorIds() != null)
		{
			ObjectComposition impostor = composition.getImpostor();
			if (impostor != null)
			{
				composition = impostor;
			}
		}

		String name = composition.getName();
		return name != null && name.toLowerCase().contains("bloodwood");
	}
}

